package net.civeira.phylax.feature.identity.userpurposeconsent.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.identity.userpurposeconsent.domain.UserPurposeConsent;
import net.civeira.phylax.feature.identity.userpurposeconsent.domain.event.UserPurposeConsentEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserPurposeConsentEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserPurposeConsentEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserPurposeConsent entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
